"use strict";

const http = require("http");
const { URL } = require("url");
const { EventEmitter } = require("events");

/**
 * Dependency-free CroxyDB admin panel.
 * @module webpanel
 */

/**
 * @typedef {Object} WebPanelOptions
 * @property {string} [title="CroxyDB Panel"] Browser title and panel heading.
 * @property {string|null} [password] Password used by the login endpoint.
 * @property {string|null} [token] Bearer token or cookie token.
 * @property {boolean} [readonly=false] Blocks write endpoints when true.
 * @property {number} [pollingInterval=1200] Event polling interval in milliseconds.
 * @property {{import?: boolean, export?: boolean, deleteAll?: boolean}} [actions] Action flags.
 * @property {{primary?: string, background?: string, surface?: string, muted?: string, text?: string}} [theme] Theme colors.
 */

const DEFAULT_OPTIONS = {
  title: "CroxyDB Panel",
  password: null,
  token: null,
  readonly: false,
  pollingInterval: 1200,
  actions: {
    import: true,
    export: true,
    deleteAll: true
  },
  theme: {
    primary: "#30d158",
    background: "#050506",
    surface: "#151516",
    muted: "#8e8e93",
    text: "#f5f5f7"
  }
};

/**
 * Merges user panel options with defaults.
 * @param {WebPanelOptions} [options={}] User options.
 * @returns {WebPanelOptions}
 */
function mergeOptions(options = {}) {
  return {
    ...DEFAULT_OPTIONS,
    ...options,
    actions: { ...DEFAULT_OPTIONS.actions, ...(options.actions || {}) },
    theme: { ...DEFAULT_OPTIONS.theme, ...(options.theme || {}) }
  };
}

/**
 * Sends an HTTP response.
 * @param {http.ServerResponse} res Response object.
 * @param {number} status HTTP status code.
 * @param {*} body Response body.
 * @param {string} [type="application/json"] Content type.
 * @returns {void}
 */
function send(res, status, body, type = "application/json") {
  const payload = type === "application/json" ? JSON.stringify(body) : body;
  res.writeHead(status, {
    "Content-Type": `${type}; charset=utf-8`,
    "Cache-Control": "no-store"
  });
  res.end(payload);
}

/**
 * Parses a JSON request body.
 * @param {http.IncomingMessage} req Request object.
 * @returns {Promise<Object>}
 */
function parseBody(req) {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (chunk) => {
      body += chunk;
      if (body.length > 1024 * 1024 * 5) {
        reject(new Error("Request body is too large."));
        req.destroy();
      }
    });
    req.on("end", () => {
      if (!body) return resolve({});
      try {
        resolve(JSON.parse(body));
      } catch (err) {
        reject(new Error("Invalid JSON body."));
      }
    });
    req.on("error", reject);
  });
}

/**
 * Normalizes adapter-specific all() results into a plain object.
 * @param {*} data Adapter all() result.
 * @returns {Object}
 */
function normalizeAll(data) {
  if (Array.isArray(data)) {
    return data.reduce((acc, item) => {
      if (item && item.key !== undefined && item.value !== undefined) {
        acc[item.key] = item.value;
      }
      return acc;
    }, {});
  }
  return data || {};
}

/**
 * CroxyDB admin panel HTTP server.
 * @class
 * @extends EventEmitter
 */
class WebPanel extends EventEmitter {
  /**
   * Creates and starts a web panel.
   * @param {number} port Port to listen on.
   * @param {Object} db CroxyDB instance.
   * @param {WebPanelOptions} [options={}] Panel options.
   */
  constructor(port, db, options = {}) {
    super();
    this.port = port || 2229;
    this.db = db;
    this.options = mergeOptions(options);
    this.events = [];
    this.nextEventId = 1;
    this.boundListeners = [];

    ["set", "delete", "expire", "deleteAll"].forEach((event) => {
      if (this.db && typeof this.db.on === "function") {
        const listener = (...args) => this.recordEvent(event, args);
        this.boundListeners.push({ event, listener });
        this.db.on(event, listener);
      }
    });

    this.server = http.createServer((req, res) => {
      this.handle(req, res).catch((err) => {
        send(res, 500, { ok: false, error: err.message || String(err) });
      });
    });

    this.server.listen(this.port, () => {
      this.emit("ready", this.port);
    });
  }

  /**
   * Stores a database event for the panel event log.
   * @param {string} type Event type.
   * @param {Array<*>} args Event arguments.
   * @returns {void}
   */
  recordEvent(type, args) {
    this.events.push({
      id: this.nextEventId++,
      type,
      key: args[0],
      value: args[1],
      at: new Date().toISOString()
    });
    if (this.events.length > 250) {
      this.events.shift();
    }
  }

  /**
   * Checks whether a request is authorized.
   * @param {http.IncomingMessage} req Request object.
   * @returns {boolean}
   */
  isAuthorized(req) {
    const secret = this.options.token || this.options.password;
    if (!secret) return true;
    const auth = req.headers.authorization || "";
    if (auth === `Bearer ${secret}`) return true;
    const cookie = req.headers.cookie || "";
    return cookie.split(";").some((part) => part.trim() === `croxydb_panel=${encodeURIComponent(secret)}`);
  }

  /**
   * Sends a readonly error when the panel is readonly.
   * @param {http.ServerResponse} res Response object.
   * @returns {boolean} True when the write should be blocked.
   */
  requireWrite(res) {
    if (!this.options.readonly) return false;
    send(res, 403, { ok: false, error: "Panel is readonly." });
    return true;
  }

  /**
   * Calls the database API, preferring async methods when available.
   * @param {string} name Database method name.
   * @param {...*} args Method arguments.
   * @returns {Promise<*>}
   */
  async call(name, ...args) {
    const asyncName = `${name}Async`;
    if (this.db && typeof this.db[asyncName] === "function") {
      return await this.db[asyncName](...args);
    }
    return await this.db[name](...args);
  }

  /**
   * Handles all panel HTTP routes.
   * @param {http.IncomingMessage} req Request object.
   * @param {http.ServerResponse} res Response object.
   * @returns {Promise<void>}
   */
  async handle(req, res) {
    const url = new URL(req.url, `http://${req.headers.host || "localhost"}`);

    if (url.pathname === "/" && req.method === "GET") {
      return send(res, 200, this.html(), "text/html");
    }

    if (url.pathname === "/api/login" && req.method === "POST") {
      const body = await parseBody(req);
      const secret = this.options.token || this.options.password;
      if (!secret || body.password === secret || body.token === secret) {
        res.writeHead(200, {
          "Content-Type": "application/json; charset=utf-8",
          "Set-Cookie": `croxydb_panel=${encodeURIComponent(secret || "open")}; Path=/; HttpOnly; SameSite=Strict`,
          "Cache-Control": "no-store"
        });
        return res.end(JSON.stringify({ ok: true }));
      }
      return send(res, 401, { ok: false, error: "Invalid password." });
    }

    if (url.pathname.startsWith("/api/") && !this.isAuthorized(req)) {
      return send(res, 401, { ok: false, error: "Unauthorized." });
    }

    if (url.pathname === "/api/state" && req.method === "GET") {
      return send(res, 200, {
        ok: true,
        title: this.options.title,
        readonly: this.options.readonly,
        hasPassword: !!(this.options.password || this.options.token),
        pollingInterval: this.options.pollingInterval,
        actions: this.options.actions,
        adapter: this.db.adapterName || "jsondb"
      });
    }

    if (url.pathname === "/api/all" && req.method === "GET") {
      return send(res, 200, { ok: true, data: normalizeAll(await this.call("all")) });
    }

    if (url.pathname === "/api/get" && req.method === "GET") {
      return send(res, 200, { ok: true, data: await this.call("get", url.searchParams.get("key")) });
    }

    if (url.pathname === "/api/set" && req.method === "POST") {
      if (this.requireWrite(res)) return;
      const body = await parseBody(req);
      const options = {};
      if (body.ttl !== undefined && body.ttl !== null && body.ttl !== "") {
        options.ttl = Number(body.ttl);
      }
      return send(res, 200, { ok: true, data: await this.call("set", body.key, body.value, options) });
    }

    if (url.pathname === "/api/delete" && req.method === "POST") {
      if (this.requireWrite(res)) return;
      const body = await parseBody(req);
      return send(res, 200, { ok: true, data: await this.call("delete", body.key) });
    }

    if (url.pathname === "/api/delete-all" && req.method === "POST") {
      if (this.requireWrite(res)) return;
      if (!this.options.actions.deleteAll) return send(res, 403, { ok: false, error: "deleteAll is disabled." });
      return send(res, 200, { ok: true, data: await this.call("deleteAll") });
    }

    if (url.pathname === "/api/import" && req.method === "POST") {
      if (this.requireWrite(res)) return;
      if (!this.options.actions.import) return send(res, 403, { ok: false, error: "Import is disabled." });
      const body = await parseBody(req);
      const data = body.data && typeof body.data === "object" ? body.data : {};
      if (body.replace) {
        await this.call("deleteAll");
      }
      for (const key of Object.keys(data)) {
        await this.call("set", key, data[key]);
      }
      return send(res, 200, { ok: true, data: true });
    }

    if (url.pathname === "/api/export" && req.method === "GET") {
      if (!this.options.actions.export) return send(res, 403, { ok: false, error: "Export is disabled." });
      res.writeHead(200, {
        "Content-Type": "application/json; charset=utf-8",
        "Content-Disposition": "attachment; filename=\"croxydb-export.json\"",
        "Cache-Control": "no-store"
      });
      return res.end(JSON.stringify(normalizeAll(await this.call("all")), null, 2));
    }

    if (url.pathname === "/api/events" && req.method === "GET") {
      const after = Number(url.searchParams.get("after") || 0);
      return send(res, 200, { ok: true, data: this.events.filter((event) => event.id > after) });
    }

    return send(res, 404, { ok: false, error: "Not found." });
  }

  /**
   * Stops the web panel server and removes database event listeners.
   * @param {Function} [callback] Called when the server closes.
   * @returns {void}
   */
  close(callback) {
    this.boundListeners.forEach(({ event, listener }) => {
      if (this.db && typeof this.db.off === "function") {
        this.db.off(event, listener);
      }
    });
    this.boundListeners = [];
    if (typeof this.server.closeIdleConnections === "function") {
      this.server.closeIdleConnections();
    }
    this.server.close(callback);
  }

  /**
   * Returns the panel HTML document.
   * @returns {string}
   */
  html() {
    const theme = this.options.theme;
    return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${this.options.title}</title>
<style>
:root {
  --primary: ${theme.primary};
  --bg: ${theme.background};
  --surface: ${theme.surface};
  --muted: ${theme.muted};
  --text: ${theme.text};
  --line: #2c2c2e;
  --danger: #ff453a;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  color: var(--text);
  background: radial-gradient(circle at top left, rgba(48, 209, 88, .12), transparent 28%), var(--bg);
  font: 14px/1.45 -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", sans-serif;
}
button, input, textarea { font: inherit; }
button {
  border: 1px solid var(--line);
  background: #1f1f21;
  color: var(--text);
  border-radius: 8px;
  padding: 9px 12px;
  cursor: pointer;
}
button:hover { border-color: var(--primary); }
button.primary { background: var(--primary); color: #061108; border-color: var(--primary); font-weight: 700; }
button.danger { color: #fff; border-color: rgba(255, 69, 58, .45); background: rgba(255, 69, 58, .16); }
button:disabled { opacity: .45; cursor: not-allowed; }
input, textarea {
  width: 100%;
  border: 1px solid var(--line);
  background: #111112;
  color: var(--text);
  border-radius: 8px;
  padding: 10px 12px;
  outline: none;
}
input:focus, textarea:focus { border-color: var(--primary); box-shadow: 0 0 0 3px rgba(48, 209, 88, .16); }
textarea { min-height: 270px; resize: vertical; font-family: "SF Mono", Consolas, monospace; }
.app { min-height: 100vh; display: grid; grid-template-columns: 320px minmax(0, 1fr); }
.sidebar { border-right: 1px solid var(--line); background: rgba(16, 16, 18, .82); backdrop-filter: blur(18px); padding: 22px; }
.brand { display: flex; align-items: center; gap: 12px; margin-bottom: 22px; }
.mark { width: 32px; height: 32px; border-radius: 9px; background: var(--primary); box-shadow: 0 0 34px rgba(48, 209, 88, .35); }
.brand h1 { font-size: 18px; margin: 0; letter-spacing: 0; }
.brand p { margin: 2px 0 0; color: var(--muted); font-size: 12px; }
.toolbar { display: grid; gap: 10px; margin-bottom: 18px; }
.keys { display: grid; gap: 6px; max-height: calc(100vh - 210px); overflow: auto; padding-right: 4px; }
.key {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  border: 1px solid transparent; border-radius: 8px; padding: 9px 10px; color: #d7d7da;
}
.key:hover, .key.active { background: #202023; border-color: #303033; }
.key code { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.main { padding: 24px; display: grid; grid-template-rows: auto 1fr; gap: 18px; }
.top { display: flex; justify-content: space-between; align-items: center; gap: 14px; }
.status { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; color: var(--muted); }
.pill { border: 1px solid var(--line); background: #171719; border-radius: 999px; padding: 6px 9px; }
.grid { display: grid; grid-template-columns: minmax(0, 1.35fr) minmax(280px, .65fr); gap: 18px; align-items: start; }
.panel { background: rgba(21, 21, 22, .86); border: 1px solid var(--line); border-radius: 8px; padding: 16px; box-shadow: 0 24px 80px rgba(0, 0, 0, .25); }
.row { display: grid; grid-template-columns: 1fr 150px; gap: 10px; margin-bottom: 12px; }
.actions { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 12px; }
.hint { color: var(--muted); font-size: 12px; margin-top: 8px; }
.events { display: grid; gap: 8px; max-height: 330px; overflow: auto; }
.event { border: 1px solid var(--line); border-radius: 8px; padding: 9px; background: #101012; }
.event strong { color: var(--primary); }
.login { min-height: 100vh; display: grid; place-items: center; padding: 20px; }
.login .panel { width: min(420px, 100%); }
.hidden { display: none !important; }
@media (max-width: 860px) {
  .app { grid-template-columns: 1fr; }
  .sidebar { border-right: 0; border-bottom: 1px solid var(--line); }
  .keys { max-height: 280px; }
  .grid { grid-template-columns: 1fr; }
  .top { align-items: flex-start; flex-direction: column; }
}
</style>
</head>
<body>
<div id="login" class="login hidden">
  <div class="panel">
    <div class="brand"><div class="mark"></div><div><h1>${this.options.title}</h1><p>Secure panel access</p></div></div>
    <input id="password" type="password" placeholder="Panel password">
    <div class="actions"><button class="primary" id="loginBtn">Login</button></div>
    <div class="hint" id="loginError"></div>
  </div>
</div>
<div id="app" class="app hidden">
  <aside class="sidebar">
    <div class="brand"><div class="mark"></div><div><h1>${this.options.title}</h1><p id="subtitle">Loading</p></div></div>
    <div class="toolbar">
      <input id="search" placeholder="Search keys or values">
      <button id="newKey">New key</button>
      <button id="refresh">Refresh</button>
    </div>
    <div id="keys" class="keys"></div>
  </aside>
  <main class="main">
    <div class="top">
      <div class="status">
        <span class="pill" id="adapter">adapter</span>
        <span class="pill" id="count">0 keys</span>
        <span class="pill" id="readonly"></span>
      </div>
      <div class="actions">
        <button id="exportBtn">Export</button>
        <button id="importBtn">Import</button>
        <button class="danger" id="deleteAllBtn">Delete all</button>
      </div>
    </div>
    <div class="grid">
      <section class="panel">
        <div class="row">
          <input id="keyInput" placeholder="key.path">
          <input id="ttlInput" type="number" min="0" placeholder="TTL ms">
        </div>
        <textarea id="valueInput" spellcheck="false" placeholder='{"hello":"croxydb"}'></textarea>
        <div class="actions">
          <button class="primary" id="saveBtn">Save</button>
          <button class="danger" id="deleteBtn">Delete key</button>
        </div>
        <div class="hint" id="message">Select a key or create a new one.</div>
      </section>
      <section class="panel">
        <h2 style="font-size:15px;margin:0 0 12px;letter-spacing:0;">Events</h2>
        <div id="events" class="events"></div>
      </section>
    </div>
  </main>
</div>
<script>
const state = { all: {}, filtered: {}, selected: "", lastEvent: 0, config: null };
const el = (id) => document.getElementById(id);

async function api(path, options = {}) {
  const res = await fetch(path, {
    ...options,
    headers: { "Content-Type": "application/json", ...(options.headers || {}) }
  });
  const json = await res.json();
  if (!json.ok) throw new Error(json.error || "Request failed.");
  return json.data === undefined ? json : json.data;
}

function flatten(obj, prefix = "", out = {}) {
  if (!obj || typeof obj !== "object" || Array.isArray(obj)) {
    if (prefix) out[prefix] = obj;
    return out;
  }
  const keys = Object.keys(obj);
  if (!keys.length && prefix) out[prefix] = obj;
  keys.forEach((key) => {
    const next = prefix ? prefix + "." + key : key;
    const value = obj[key];
    if (value && typeof value === "object" && !Array.isArray(value)) flatten(value, next, out);
    else out[next] = value;
  });
  return out;
}

function renderKeys() {
  const q = el("search").value.toLowerCase();
  const flat = flatten(state.all);
  state.filtered = Object.keys(flat).filter((key) => {
    return !q || key.toLowerCase().includes(q) || JSON.stringify(flat[key]).toLowerCase().includes(q);
  }).sort().reduce((acc, key) => (acc[key] = flat[key], acc), {});
  el("count").textContent = Object.keys(state.filtered).length + " keys";
  el("keys").innerHTML = Object.keys(state.filtered).map((key) => {
    return '<button class="key ' + (key === state.selected ? 'active' : '') + '" data-key="' + encodeURIComponent(key) + '"><code>' + escapeHtml(key) + '</code></button>';
  }).join("") || '<div class="hint">No keys found.</div>';
  document.querySelectorAll(".key").forEach((btn) => btn.onclick = () => selectKey(decodeURIComponent(btn.dataset.key)));
}

function selectKey(key) {
  state.selected = key;
  el("keyInput").value = key;
  el("valueInput").value = JSON.stringify(state.filtered[key], null, 2);
  renderKeys();
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char]));
}

async function refresh() {
  state.all = await api("/api/all");
  renderKeys();
  if (state.selected && state.filtered[state.selected] !== undefined) selectKey(state.selected);
}

async function save() {
  const key = el("keyInput").value.trim();
  if (!key) return note("Key is required.");
  let value;
  try { value = JSON.parse(el("valueInput").value); }
  catch (err) { return note("Value must be valid JSON."); }
  await api("/api/set", { method: "POST", body: JSON.stringify({ key, value, ttl: el("ttlInput").value }) });
  note("Saved.");
  state.selected = key;
  await refresh();
}

async function deleteKey() {
  const key = el("keyInput").value.trim();
  if (!key) return note("Key is required.");
  await api("/api/delete", { method: "POST", body: JSON.stringify({ key }) });
  state.selected = "";
  el("keyInput").value = "";
  el("valueInput").value = "";
  note("Deleted.");
  await refresh();
}

async function loadEvents() {
  const events = await api("/api/events?after=" + state.lastEvent);
  if (!events.length) return;
  state.lastEvent = events[events.length - 1].id;
  const html = events.reverse().map((event) => '<div class="event"><strong>' + escapeHtml(event.type) + '</strong> <code>' + escapeHtml(event.key || "") + '</code><div class="hint">' + escapeHtml(new Date(event.at).toLocaleTimeString()) + '</div></div>').join("");
  el("events").innerHTML = html + el("events").innerHTML;
}

function note(text) { el("message").textContent = text; }

async function init() {
  try {
    const cfg = await api("/api/state");
    state.config = cfg;
    el("app").classList.remove("hidden");
    el("subtitle").textContent = cfg.readonly ? "Readonly mode" : "Live editor";
    el("adapter").textContent = cfg.adapter;
    el("readonly").textContent = cfg.readonly ? "readonly" : "editable";
    el("saveBtn").disabled = cfg.readonly;
    el("deleteBtn").disabled = cfg.readonly;
    el("deleteAllBtn").disabled = cfg.readonly || !cfg.actions.deleteAll;
    el("importBtn").disabled = cfg.readonly || !cfg.actions.import;
    el("exportBtn").disabled = !cfg.actions.export;
    await refresh();
    setInterval(loadEvents, cfg.pollingInterval || 1200);
  } catch (err) {
    el("login").classList.remove("hidden");
  }
}

el("loginBtn").onclick = async () => {
  try {
    await api("/api/login", { method: "POST", body: JSON.stringify({ password: el("password").value }) });
    el("login").classList.add("hidden");
    init();
  } catch (err) {
    el("loginError").textContent = err.message;
  }
};
el("newKey").onclick = () => { state.selected = ""; el("keyInput").value = ""; el("valueInput").value = "{}"; note("New key."); renderKeys(); };
el("refresh").onclick = refresh;
el("search").oninput = renderKeys;
el("saveBtn").onclick = save;
el("deleteBtn").onclick = deleteKey;
el("exportBtn").onclick = () => location.href = "/api/export";
el("importBtn").onclick = async () => {
  const raw = prompt("Paste JSON to import");
  if (!raw) return;
  try {
    await api("/api/import", { method: "POST", body: JSON.stringify({ data: JSON.parse(raw), replace: false }) });
    note("Imported.");
    refresh();
  } catch (err) { note(err.message); }
};
el("deleteAllBtn").onclick = async () => {
  if (!confirm("Delete all data?")) return;
  await api("/api/delete-all", { method: "POST", body: "{}" });
  state.selected = "";
  await refresh();
};
init();
</script>
</body>
</html>`;
  }
}

module.exports = WebPanel;
